out=[]
for sid,name,level,steps,end in META:
    out.append(dict(id=sid,name=name,level=level,steps=[dict(tr=t,goal=g) for t,g in steps],endTr=end))
langs={}
for lg,d in D.items():
    langs[lg]=dict(clarify=d['clarify'],s={})
    for sid,(st,end) in d['s'].items():
        m=[x for x in META if x[0]==sid][0]
        assert len(st)==len(m[3]),(lg,sid)
        langs[lg]['s'][sid]=dict(steps=[dict(say=a,hint=b,kw=[k.strip().lower() for k in c.split(',') if k.strip()] if True else []) for a,b,c in st],end=end)
json.dump(dict(scenarios=out,langs=langs),open('../data/scenarios.json','w'),ensure_ascii=False,indent=0)
print('ok',len(out),list(langs))
